import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { describe, expect, it } from 'vitest'
import { MIDDLE_KNUCKLE, normalize, type Handedness, type Point } from './normalize'

// The cases generated by Python (training/scripts/make_normalize_cases.py).
// Tests run from the web/ folder (process.cwd()), so the file is in ../shared/.
interface Case {
  handedness: Handedness
  points: Point[]
  expected: number[]
}
const { cases } = JSON.parse(
  readFileSync(resolve(process.cwd(), '../shared/normalize_cases.json'), 'utf8'),
) as { cases: Case[] }

// A simple fake hand: point i is at (i, 2i, -i) cm, so the wrist (i = 0) is at 0.
const HAND: Point[] = Array.from({ length: 21 }, (_, i) => [i * 0.01, i * 0.02, -i * 0.01])

function point(flat: number[], i: number): number[] {
  return flat.slice(i * 3, i * 3 + 3)
}

describe('R20: normalization', () => {
  it('R20: gives 63 numbers with the wrist at 0', () => {
    const out = normalize(HAND, 'Right')
    expect(out).toHaveLength(63)
    expect(point(out, 0)).toEqual([0, 0, 0])
  })

  it('R20: the wrist-to-middle-knuckle length becomes 1', () => {
    expect(Math.hypot(...point(normalize(HAND, 'Right'), MIDDLE_KNUCKLE))).toBeCloseTo(1)
  })

  it('R20: position and hand size do not matter', () => {
    const movedAndBigger = HAND.map(([x, y, z]) => [x * 2 + 0.3, y * 2 - 0.1, z * 2] as Point)
    const a = normalize(movedAndBigger, 'Right')
    normalize(HAND, 'Right').forEach((v, i) => expect(a[i]).toBeCloseTo(v))
  })

  it('R20: a left hand is the mirror of the right hand (x flipped)', () => {
    const right = normalize(HAND, 'Right')
    const left = normalize(HAND, 'Left')
    for (let i = 0; i < 21; i++) {
      const [rx, ry, rz] = point(right, i)
      const [lx, ly, lz] = point(left, i)
      expect(lx).toBeCloseTo(-rx)
      expect([ly, lz]).toEqual([ry, rz])
    }
  })

  it('R20: rejects a wrong number of points or a size of 0', () => {
    expect(() => normalize(HAND.slice(0, 20), 'Right')).toThrow()
    expect(() => normalize(Array.from({ length: 21 }, () => [0, 0, 0] as Point), 'Right')).toThrow()
  })
})

describe('R21: TypeScript gives the same numbers as Python', () => {
  it.each(cases.map((c, i) => [i, c] as const))('R21: shared case %i', (_, c) => {
    const out = normalize(c.points, c.handedness)
    // toBeCloseTo(v, 9): equal to 9 decimals. Tiny differences can come from rounding.
    out.forEach((v, i) => expect(v).toBeCloseTo(c.expected[i], 9))
  })
})
